--- clean/crates/crypto/circuits/src/scalar/reduction_inspection.rs
+++ overlay/crates/crypto/circuits/src/scalar/reduction_inspection.rs
@@ -0,0 +1,138 @@
+//! Bounded, opt-in capture of the existing authorization reduction only.
+//! Constants are read as native values; recording never allocates circuit nodes.
+use super::*;
+use super::inspection::Observed;
+use commonware_cryptography::zk::circuit::CircuitIdx;
+use std::cell::RefCell;
+
+#[derive(Clone,PartialEq,Eq)]
+pub struct Report {
+    pub value: CircuitIdx,
+    pub quotient: CircuitIdx,
+    pub remainder: CircuitIdx,
+    pub quotient_bits: Vec<CircuitIdx>,
+    pub remainder_bits: Vec<CircuitIdx>,
+    pub quotient_end: Observed,
+    pub remainder_end: Observed,
+    pub terminal_end: Observed,
+    pub equation: CircuitIdx,
+    pub terminal_gate: CircuitIdx,
+    pub steps: [Vec<[Observed;6]>;3],
+    pub consumer: Option<(CircuitIdx,CircuitIdx)>,
+}
+#[derive(Default)]
+struct State {
+    calls: usize,
+    active: bool,
+    phase: usize,
+    remainder: Option<CircuitIdx>,
+    remainder_end: Option<Observed>,
+    steps: [Vec<[Observed;6]>;3],
+    report: Option<Report>,
+    error: bool,
+}
+thread_local! { static STATE: RefCell<Option<State>> = const { RefCell::new(None) }; }
+pub struct Capture { _thread: std::marker::PhantomData<std::rc::Rc<()>> }
+impl Drop for Capture { fn drop(&mut self) { STATE.with(|state| *state.borrow_mut()=None); } }
+pub fn begin() -> anyhow::Result<Capture> {
+    STATE.with(|state| {
+        let mut state=state.borrow_mut();
+        anyhow::ensure!(state.is_none(),"nested reduction capture");
+        *state=Some(State::default());
+        Ok(Capture { _thread:std::marker::PhantomData })
+    })
+}
+fn observe(value:&Var<'_,Scalar>) -> Observed {
+    match value.inspect_circuit_idx() {
+        Some(index)=>Observed::Source(index),
+        None=>Observed::Native(value.inspect_native().expect("invalid observed variable").clone()),
+    }
+}
+pub(super) fn start(remainder:&Var<'_,Scalar>) {
+    STATE.with(|state| {
+        if let Some(state)=state.borrow_mut().as_mut() {
+            state.calls+=1;
+            if state.calls != 1 { state.error=true;state.active=false;return; }
+            state.remainder=remainder.inspect_circuit_idx();
+            state.active=true;
+            state.phase=0;
+        }
+    });
+}
+pub(crate) fn step(values:[&Var<'_,Scalar>;6]) {
+    STATE.with(|state| {
+        if let Some(state)=state.borrow_mut().as_mut() {
+            if !state.active {return;}
+            let bound=if state.phase==0 {4} else {252};
+            if state.phase>=3 || state.steps[state.phase].len()>=bound {state.error=true;return;}
+            state.steps[state.phase].push(values.map(observe));
+        }
+    });
+}
+pub(super) fn quotient_end() {
+    STATE.with(|state| {
+        if let Some(state)=state.borrow_mut().as_mut() {
+            if state.active {state.phase=1;}
+        }
+    });
+}
+pub(super) fn canonical_end(value:&Var<'_,Scalar>,ending:&Var<'_,Scalar>) {
+    STATE.with(|state| {
+        if let Some(state)=state.borrow_mut().as_mut() {
+            if state.active && value.inspect_circuit_idx()==state.remainder {
+                state.remainder_end=Some(observe(ending));state.phase=2;
+            }
+        }
+    });
+}
+pub(super) fn finish<'ctx>(value:&Var<'ctx,Scalar>,quotient:&Var<'ctx,Scalar>,remainder:&Var<'ctx,Scalar>,
+    quotient_bits:&[BoolVar<'ctx,Scalar>],remainder_bits:&[BoolVar<'ctx,Scalar>],
+    quotient_end:&Var<'ctx,Scalar>,terminal_end:&Var<'ctx,Scalar>,equation:&Var<'ctx,Scalar>,gate:&Var<'ctx,Scalar>) {
+    STATE.with(|state| {
+        if let Some(state)=state.borrow_mut().as_mut() {
+            if !state.active {return;}
+            state.active=false;
+            let [Some(value),Some(quotient),Some(remainder),Some(equation),Some(terminal_gate)]=
+                [value,quotient,remainder,equation,gate].map(|v|v.inspect_circuit_idx()) else {state.error=true;return;};
+            let Some(remainder_end)=state.remainder_end.take() else {state.error=true;return;};
+            if state.steps.iter().map(Vec::len).collect::<Vec<_>>()!=[4,252,252] {state.error=true;return;}
+            let indices=|bits:&[BoolVar<'_,Scalar>]|bits.iter().map(|b|b.var().inspect_circuit_idx()).collect::<Option<Vec<_>>>();
+            let (Some(quotient_bits),Some(remainder_bits))=(indices(quotient_bits),indices(remainder_bits)) else {state.error=true;return;};
+            state.report=Some(Report {value,quotient,remainder,quotient_bits,remainder_bits,
+                quotient_end:observe(quotient_end),remainder_end,terminal_end:observe(terminal_end),
+                equation,terminal_gate,steps:std::mem::take(&mut state.steps),consumer:None});
+        }
+    });
+}
+pub(crate) fn consumer(value:&Var<'_,Scalar>,inverse:&Var<'_,Scalar>,bits:&[BoolVar<'_,Scalar>]) {
+    STATE.with(|state| {
+        if let Some(state)=state.borrow_mut().as_mut() {
+            let Some(report)=state.report.as_mut() else {return;};
+            let (Some(value),Some(inverse))=(value.inspect_circuit_idx(),inverse.inspect_circuit_idx()) else {state.error=true;return;};
+            if report.consumer.is_some() || bits.iter().map(|b|b.var().inspect_circuit_idx()).collect::<Option<Vec<_>>>()!=Some(report.remainder_bits.clone()) {state.error=true;return;}
+            report.consumer=Some((value,inverse));
+        }
+    });
+}
+pub fn take() -> anyhow::Result<Report> {
+    STATE.with(|state| {
+        let mut state=state.borrow_mut();
+        let state=state.as_mut().ok_or_else(||anyhow::anyhow!("inactive reduction capture"))?;
+        anyhow::ensure!(!state.error && !state.active && state.calls==1,"incomplete/multiple reduction capture");
+        let report=state.report.take().ok_or_else(||anyhow::anyhow!("missing reduction report"))?;
+        anyhow::ensure!(report.consumer.is_some(),"missing actual nonzero IVK consumer");
+        Ok(report)
+    })
+}
+#[cfg(test)]
+mod tests {
+    use super::*;
+    #[test]
+    fn reduction_session_cleanup_is_exclusive() {
+        {let _capture=begin().unwrap();assert!(begin().is_err());assert!(take().is_err());}
+        let result=std::panic::catch_unwind(||{let _capture=begin().unwrap();panic!("synthetic reduction failure");});
+        assert!(result.is_err());
+        {let _capture=begin().unwrap();assert!(take().is_err());}
+        assert!(take().is_err());
+    }
+}
